from machine import I2C,UART,Pinfrom  Sengo1  import *import time# 等待Sengo1完成操作系统的初始化。此等待时间不可去掉，避免出现Sengo1尚未初始化完毕主控器已经开发发送指令的情况time.sleep(2)# 选择UART或者I2C通讯模式，Sengo1出厂默认为I2C模式，短按模式按键可以切换# 4种UART通讯模式：UART9600（标准协议指令），UART57600（标准协议指令），UART115200（标准协议指令），Simple9600（简单协议指令），# 参看“简单协议指令”# https://tosee.readthedocs.io/zh/latest/Common/Protocol/index.html#section-6########################################################################################################## port = UART(2,rx=Pin(16),tx=Pin(17),baudrate=9600)port = I2C(1,scl=Pin(22),sda=Pin(21),freq=400000)# Sengo1通讯地址：0x60。如果I2C总线挂接多个设备，请避免出现地址冲突sengo1 = Sengo1(0x60)err = sengo1.begin(port)if err != SENTRY_OK:    print(f"Initialization failed，error code:{err}")else:    print("Initialization succeeded")# 1、参考文档（注：Sengo1与Sentry1是两款产品）# https://tosee.readthedocs.io/zh/latest/Sentry1/Vision/index.html#chapter-vs1-vision-line-index# 2、算法的常见应用：巡线；# 3、使用时请注意：线条应与背景有明显差异，常见为白纸黑线；线条的宽度适中，譬如1.5cm；地图的表面不应光滑，避免发生反光问题；# 4、Sengo1每次只能运行一种识别算法；# 5、正常使用时，应由主控板通过指令控制Sengo1算法的开启与关闭，而不是通过Sengo1的按键进行操作；err = sengo1.VisionBegin(sengo1_vision_e.kVisionLine)if err != SENTRY_OK:    print(f"Starting algo Line failed，error code:{err}")else:    print("Starting algo Line succeeded")def Left():  print("Left")  def Hard_Left():  print("Hard Left")  def Right():  print("Right")  def Hard_Right():  print("Hard Right")  def Forward():  print("Forward")while True:  obj_num = sengo1.GetValue(sengo1_vision_e.kVisionLine, sentry_obj_info_e.kStatus)  # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。  # Sengo最多输出1个识别结果。  if obj_num:    angle = (sengo1.GetValue(sengo1_vision_e.kVisionLine,sentry_obj_info_e.kLabel))    print("angle = %d"%angle)    if (angle < 45):      Hard_Right()    if ((45 < angle) and (angle < 80)):      Right()    if ((80 < angle) and (angle < 100)):      Forward()    if ((100 < angle) and (angle < 135)):      Left()    if (135 < angle):      Hard_Left()  print("\n")